// Command gen writes test/fixtures/handshake.json: a DERP handshake as
// tailscale.com's own derp.Client produces it. The relay's tests replay it
// to check that the Worker reads the client's sealed ClientInfo the same
// way derper does.
//
// The keys it writes are throwaway test keys. Regenerate with:
//
//	cd test/fixtures/gen && go run . > ../handshake.json
package main

import (
	"bufio"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"io"
	"log"
	"net"
	"os"
	"strings"

	"tailscale.com/derp"
	"tailscale.com/types/key"
)

type fixture struct {
	Note             string `json:"note"`
	TailscaleVersion string `json:"tailscaleVersion"`
	ServerPrivate    string `json:"serverPrivate"`
	ServerPublic     string `json:"serverPublic"`
	ClientPrivate    string `json:"clientPrivate"`
	ClientPublic     string `json:"clientPublic"`
	ServerKeyFrame   string `json:"serverKeyFrame"`
	ClientInfoFrame  string `json:"clientInfoFrame"`
}

// privHex returns the raw 32-byte private key as hex.
func privHex(k key.NodePrivate) string {
	b, err := k.MarshalText()
	if err != nil {
		log.Fatal(err)
	}
	return strings.TrimPrefix(string(b), "privkey:")
}

func main() {
	server := key.NewNode()
	client := key.NewNode()

	// The ServerKey frame: type 0x01, length, magic, server public key.
	body := append([]byte(derp.Magic), server.Public().AppendTo(nil)...)
	serverKeyFrame := append([]byte{byte(derp.FrameServerKey), 0, 0, 0, 0}, body...)
	binary.BigEndian.PutUint32(serverKeyFrame[1:5], uint32(len(body)))

	cc, sc := net.Pipe()
	got := make(chan []byte, 1)
	go func() {
		if _, err := sc.Write(serverKeyFrame); err != nil {
			log.Fatal(err)
		}
		hdr := make([]byte, 5)
		if _, err := io.ReadFull(sc, hdr); err != nil {
			log.Fatal(err)
		}
		rest := make([]byte, binary.BigEndian.Uint32(hdr[1:]))
		if _, err := io.ReadFull(sc, rest); err != nil {
			log.Fatal(err)
		}
		got <- append(hdr, rest...)
	}()

	brw := bufio.NewReadWriter(bufio.NewReader(cc), bufio.NewWriter(cc))
	if _, err := derp.NewClient(client, cc, brw, log.Printf, derp.CanAckPings(true)); err != nil {
		log.Fatal(err)
	}
	clientInfoFrame := <-got

	out := fixture{
		Note:             "Throwaway keys for tests only. Generated by test/fixtures/gen.",
		TailscaleVersion: tailscaleVersion(),
		ServerPrivate:    privHex(server),
		ServerPublic:     hex.EncodeToString(server.Public().AppendTo(nil)),
		ClientPrivate:    privHex(client),
		ClientPublic:     hex.EncodeToString(client.Public().AppendTo(nil)),
		ServerKeyFrame:   hex.EncodeToString(serverKeyFrame),
		ClientInfoFrame:  hex.EncodeToString(clientInfoFrame),
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		log.Fatal(err)
	}
}

// tailscaleVersion reads the tailscale.com version from go.mod, so the
// fixture says which client code produced it.
func tailscaleVersion() string {
	b, err := os.ReadFile("go.mod")
	if err != nil {
		return "unknown"
	}
	for _, line := range strings.Split(string(b), "\n") {
		f := strings.Fields(line)
		if len(f) >= 2 && f[0] == "tailscale.com" {
			return f[1]
		}
		if len(f) >= 3 && f[0] == "require" && f[1] == "tailscale.com" {
			return f[2]
		}
	}
	return "unknown"
}
